import java.net.*;
import java.nio.file.*;

public final class Matchmaking680Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static GunnyServer.Session person(CloudStore.Memory store,int i)throws Exception{String email="p"+i+"@680.test";store.register(email,"test-password-123","Player "+i);var s=new GunnyServer.Session();s.id=store.login(email,"test-password-123").userId;s.profile=store.profile(s.id);s.async=s.social=s.matchmaking=s.modern=true;s.lastSeen=System.currentTimeMillis();return s;}
 static GunnyServer.Room room(GunnyServer server,GunnyServer.Session host,GunnyServer.Session ally){var r=server.new Room(host,1,2,-1);r.customAllies=r.strict=true;r.seconds=12;r.mapLimit=6;r.members[2]=ally;r.refreshWaiting();if(ally!=null){ally.room=r.id;ally.armed=true;}host.room=r.id;server.rooms.put(r.id,r);return r;}
 public static void main(String[] args)throws Exception{CloudStore.Memory store=new CloudStore.Memory();try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){
  var a=person(store,0);var b=person(store,1);var c=person(store,2);var d=person(store,3);var e=person(store,4);var f=person(store,5);
  var solo=room(server,a,null);server.matchmaker.start(a,0,"");ok(solo.queued&&solo.phase==0,"Lone host queues instead of requiring an opponent already in room");var pair=room(server,b,c);server.matchmaker.start(b,0,"");ok(pair.queued&&solo.phase==0,"Two-person party cannot match a one-person room");var otherSolo=room(server,d,null);server.matchmaker.start(d,0,"");ok(otherSolo.phase==3&&otherSolo.count==2&&otherSolo.members[1]==a&&a.room==otherSolo.id&&!server.rooms.containsKey(solo.id),"Two lone private rooms merge into exactly 1v1");
  var otherPair=room(server,e,f);f.armed=false;boolean denied=false;try{server.matchmaker.start(e,0,"");}catch(IllegalArgumentException ex){denied=true;}ok(denied&&otherPair.phase==0,"Unready ally blocks matchmaking");f.armed=true;server.matchmaker.start(e,0,"");ok(otherPair.phase==3&&otherPair.count==4&&otherPair.members[0]==e&&otherPair.members[2]==f&&otherPair.members[1]==b&&otherPair.members[3]==c,"2v2 merge preserves both allied rosters");
  var g=person(store,6);var h=person(store,7);var first=room(server,g,null);var target=room(server,h,null);target.secret="abcd";denied=false;try{server.matchmaker.start(g,target.id,"wrong");}catch(IllegalArgumentException ex){denied=true;}ok(denied&&first.phase==0&&target.phase==0,"Room challenge validates opponent password before moving anyone");server.matchmaker.start(g,target.id,"abcd");ok(first.phase==3&&first.members[1]==h,"Correct code and password start the private room duel");
  var i=person(store,8);var j=person(store,9);var privateRoom=room(server,i,null);var soloQueue=server.new Room(j,-1,0,-1);soloQueue.kind=1;soloQueue.strict=true;j.room=soloQueue.id;server.rooms.put(soloQueue.id,soloQueue);server.matchmaker.start(i,0,"");ok(privateRoom.queued&&soloQueue.phase==0,"Private room queue does not consume a Solo-mode player");
  GunnyServer.Session[] six=new GunnyServer.Session[6];for(int n=0;n<6;n++)six[n]=person(store,10+n);var ta=server.new Room(six[0],1,2,-1,true);var tb=server.new Room(six[3],1,2,-1,true);ta.kind=tb.kind=2;ta.strict=tb.strict=true;for(int n=0;n<3;n++){ta.members[n*2]=six[n];tb.members[n*2]=six[n+3];six[n].room=ta.id;six[n+3].room=tb.id;}ta.refreshWaiting();tb.refreshWaiting();for(var member:six)member.armed=true;server.rooms.put(ta.id,ta);server.rooms.put(tb.id,tb);server.matchmaker.start(six[0],0,"");ok(ta.phase==0&&ta.queued,"A ready team of three waits for another team");server.matchmaker.start(six[3],0,"");ok(tb.phase==3&&tb.count==6&&tb.members[0]==six[3]&&tb.members[2]==six[4]&&tb.members[4]==six[5]&&tb.members[1]==six[0]&&tb.members[3]==six[1]&&tb.members[5]==six[2],"Two complete teams match as 3v3 with all allies preserved");
 }System.out.println("All 6.8.0 room matchmaking checks passed");}
}
